/* ==========================================================================
   PORTAL PRINCIPAL / MASTER LAUNCHPAD (ACCESOS DIRECTOS E2E)
   Directivas: DESIGN.md • Strict Light Tech • Grand Interactive Launchpad
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;700&family=Outfit:wght@500;600;700;800&display=swap');
@import './variables.css';

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

html, body {
  width: 100%;
  min-height: 100vh;
  background-color: #F8FAFC;
  font-family: var(--font-body);
  color: var(--text-primary);
  -webkit-font-smoothing: antialiased;
}

/* Background Atmospheric Glows */
.portal-bg-canvas {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  overflow: hidden;
}

.portal-glow-1 {
  position: absolute;
  top: -10%;
  left: 20%;
  width: 600px;
  height: 600px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(1, 157, 244, 0.08) 0%, transparent 70%);
  filter: blur(40px);
}

.portal-glow-2 {
  position: absolute;
  bottom: 0%;
  right: 15%;
  width: 550px;
  height: 550px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(0, 212, 255, 0.08) 0%, transparent 70%);
  filter: blur(40px);
}

/* Main Container */
.portal-container {
  max-width: 1320px;
  margin: 0 auto;
  padding: 40px 28px 80px 28px;
  position: relative;
  z-index: 10;
  display: flex;
  flex-direction: column;
  gap: 36px;
}

/* ==========================================================================
   1. PORTAL HEADER
   ========================================================================== */
.portal-top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1.5px solid #E2E8F0;
  padding-bottom: 24px;
}

.portal-brand-block {
  display: flex;
  align-items: center;
  gap: 16px;
}

.portal-logo-m {
  width: 48px;
  height: 48px;
  border-radius: 14px;
  background: linear-gradient(135deg, var(--movistar-blue), #0066CC);
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 24px;
  font-weight: 800;
  box-shadow: 0 8px 20px rgba(1, 157, 244, 0.3);
}

.portal-brand-info h1 {
  font-family: var(--font-heading);
  font-size: 24px;
  font-weight: 800;
  color: var(--deep-indigo);
  display: flex;
  align-items: center;
  gap: 10px;
}

.portal-badge-hackathon {
  font-family: var(--font-mono);
  font-size: 11px;
  background: var(--aura-cyan-subtle);
  color: var(--movistar-blue);
  border: 1px solid rgba(0, 212, 255, 0.4);
  padding: 3px 10px;
  border-radius: 20px;
  font-weight: 700;
}

.portal-brand-info p {
  font-size: 13px;
  color: var(--text-secondary);
  margin-top: 2px;
}

.portal-status-cluster {
  display: flex;
  align-items: center;
  gap: 12px;
}

.status-pill-online {
  background: #F0FDF4;
  border: 1px solid #BBF7D0;
  color: #166534;
  font-size: 12px;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 20px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.pulse-dot-green {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #00C853;
  box-shadow: 0 0 10px #00C853;
}

/* ==========================================================================
   2. HERO BANNER
   ========================================================================== */
.portal-hero-intro {
  text-align: center;
  max-width: 820px;
  margin: 10px auto 0 auto;
}

.portal-hero-intro h2 {
  font-family: var(--font-heading);
  font-size: 34px;
  font-weight: 800;
  color: var(--deep-indigo);
  letter-spacing: -0.5px;
  line-height: 1.25;
  margin-bottom: 10px;
}

.portal-hero-intro p {
  font-size: 15px;
  color: var(--text-secondary);
  line-height: 1.55;
}

/* ==========================================================================
   3. GRAND BENTO GRID DE ACCESOS DIRECTOS (CARDS GIGANTES)
   ========================================================================== */
.portal-cards-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-top: 10px;
}

@media (max-width: 900px) {
  .portal-cards-grid {
    grid-template-columns: 1fr;
  }
}

/* Grand Access Card */
.grand-access-card {
  background: #FFFFFF;
  border: 1.5px solid #E2E8F0;
  border-radius: 24px;
  padding: 30px 32px;
  text-decoration: none;
  color: inherit;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 280px;
  box-shadow: 0 4px 20px rgba(11, 25, 44, 0.04);
  position: relative;
  overflow: hidden;
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.grand-access-card:hover {
  transform: translateY(-4px);
  border-color: var(--movistar-blue);
  box-shadow: 0 20px 40px rgba(1, 157, 244, 0.12), 0 0 0 1px var(--movistar-blue);
}

/* Card Header */
.card-head-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.card-icon-frame {
  width: 54px;
  height: 54px;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.1);
  transition: transform 0.3s ease;
}

.grand-access-card:hover .card-icon-frame {
  transform: scale(1.08);
}

.card-shortcut-tag {
  font-family: var(--font-mono);
  font-size: 11px;
  background: #F1F5F9;
  border: 1px solid #CBD5E1;
  color: var(--deep-indigo);
  padding: 3px 9px;
  border-radius: 8px;
  font-weight: 700;
}

.card-phase-badge {
  font-family: var(--font-heading);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
  display: block;
}

/* Card Body Typography */
.card-title-main {
  font-family: var(--font-heading);
  font-size: 21px;
  font-weight: 800;
  color: var(--deep-indigo);
  margin-bottom: 8px;
}

.card-desc-text {
  font-size: 13.5px;
  color: var(--text-secondary);
  line-height: 1.5;
  margin-bottom: 20px;
}

/* Highlights Pills Row */
.card-pills-cluster {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 24px;
}

.highlight-pill {
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 8px;
  background: #F8FAFC;
  border: 1px solid #E2E8F0;
  color: var(--deep-indigo);
}

/* Action CTA Button */
.card-action-btn-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid #F1F5F9;
  padding-top: 18px;
}

.action-cta-text {
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 800;
  color: var(--movistar-blue);
  display: flex;
  align-items: center;
  gap: 6px;
  transition: gap 0.2s ease;
}

.grand-access-card:hover .action-cta-text {
  gap: 10px;
  color: #0066CC;
}

.action-url-label {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-muted);
}

/* Card Specific Theming */
.theme-cliente .card-icon-frame {
  background: linear-gradient(135deg, #00C853, #009624);
}
.theme-cliente .card-phase-badge { color: #008738; }

.theme-operador .card-icon-frame {
  background: linear-gradient(135deg, var(--movistar-blue), #0066CC);
}
.theme-operador .card-phase-badge { color: var(--movistar-blue); }

.theme-mimovistar .card-icon-frame {
  background: linear-gradient(135deg, var(--aura-cyan), var(--movistar-blue));
}
.theme-mimovistar .card-phase-badge { color: var(--aura-cyan); }

.theme-whatsapp .card-icon-frame {
  background: linear-gradient(135deg, #25D366, #128C7E);
}
.theme-whatsapp .card-phase-badge { color: #128C7E; }

/* Full-width Banner Card for Architecture / Live Pitch */
.portal-fullwidth-card {
  grid-column: 1 / -1;
  background: linear-gradient(135deg, #0B192C 0%, #1A365D 100%);
  color: #FFFFFF;
  border-radius: 24px;
  padding: 30px 34px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border: 1px solid rgba(0, 212, 255, 0.3);
  box-shadow: 0 12px 35px rgba(11, 25, 44, 0.35);
}

@media (max-width: 800px) {
  .portal-fullwidth-card {
    flex-direction: column;
    align-items: flex-start;
    gap: 20px;
  }
}

.fullwidth-info h3 {
  font-family: var(--font-heading);
  font-size: 20px;
  font-weight: 800;
  color: #FFFFFF;
  margin-bottom: 4px;
}

.fullwidth-info p {
  font-size: 13.5px;
  color: #CBD5E1;
  max-width: 600px;
  line-height: 1.45;
}

.fullwidth-btn-group {
  display: flex;
  align-items: center;
  gap: 12px;
}

.btn-portal-white {
  background: #FFFFFF;
  color: var(--deep-indigo);
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 800;
  padding: 11px 20px;
  border-radius: 12px;
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: transform 0.2s ease;
}

.btn-portal-white:hover {
  transform: translateY(-2px);
}

/* ==========================================================================
   PORTAL PRINCIPAL / MASTER LAUNCHPAD - CONTROL & KEYBOARD SHORTCUTS
   ========================================================================== */

import { createIcons, icons } from 'lucide';

document.addEventListener('DOMContentLoaded', () => {
  createIcons({ icons });

  // Atajos de Teclado Globales desde el Portal Principal
  document.addEventListener('keydown', (e) => {
    if (e.key === '1') {
      window.location.href = './cliente.html';
    } else if (e.key === '2') {
      window.location.href = './operador.html';
    } else if (e.key === '3') {
      window.location.href = './mi-movistar.html';
    } else if (e.key === '4') {
      window.location.href = './valeria.html';
    }
  });

  console.log('🚀 Movistar Journey Tracker - Master Portal Launchpad Initialized.');
});

