/* ==========================================================================
   PERSPECTIVA DEL CLIENTE (VALERIA MENDOZA) - 100% FULLSCREEN & RESPONSIVE
   Directivas: DESIGN.md • Strict Light Tech • Zero Mockups • Fullscreen Native
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;700&family=Outfit:wght@500;600;700;800&display=swap');
@import './variables.css';

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

html, body {
  width: 100%;
  min-height: 100dvh;
  background-color: #F8FAFC;
  font-family: var(--font-body);
  color: var(--text-primary);
  display: flex;
  flex-direction: column;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* Container Wrapper: 100% Fullscreen on Mobile, Centered Clean Container on Desktop */
.phone-viewport-stage {
  width: 100%;
  min-height: 100dvh;
  max-width: 840px;
  margin: 0 auto;
  background: #FFFFFF;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  border-left: 1px solid #E2E8F0;
  border-right: 1px solid #E2E8F0;
  box-shadow: 0 4px 30px rgba(0, 0, 0, 0.03);
}

@media (max-width: 840px) {
  .phone-viewport-stage {
    max-width: 100vw;
    border-left: none;
    border-right: none;
    box-shadow: none;
  }
}

/* Phone Native Status Bar */
.phone-status-bar {
  height: 44px;
  padding: 12px 24px 0 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  font-weight: 700;
  color: var(--deep-indigo);
  background: #FFFFFF;
  border-bottom: 1px solid #F1F5F9;
  z-index: 90;
}

.status-bar-icons {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Screens Stack */
.client-screen-view {
  flex: 1;
  display: none;
  flex-direction: column;
  overflow-y: auto;
  padding-bottom: 80px;
  animation: screenFadeIn 0.35s ease-out forwards;
}

.client-screen-view.active-screen {
  display: flex;
}

/* ==========================================================================
   PANTALLA 1: APP MI MOVISTAR (DIDACTIC CONSUMPTION & SMART WARNING)
   ========================================================================== */
.app-header-brand {
  padding: 18px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #FFFFFF;
  border-bottom: 1.5px solid #F1F5F9;
}

.app-brand-left {
  display: flex;
  align-items: center;
  gap: 14px;
}

.app-brand-logo-m {
  width: 38px;
  height: 38px;
  background: linear-gradient(135deg, var(--movistar-blue), #0066CC);
  color: #FFFFFF;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 18px;
  font-weight: 800;
}

.app-user-greeting h3 {
  font-family: var(--font-heading);
  font-size: 17px;
  font-weight: 800;
  color: var(--deep-indigo);
}

.app-user-greeting p {
  font-size: 12px;
  color: var(--text-muted);
}

/* Content Body */
.app-scroll-content {
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

/* SMART ADVICE WARNING CARD (NO GENERIC ADS) */
.smart-advice-banner-card {
  background: linear-gradient(135deg, #0B192C 0%, #1A365D 100%);
  color: #FFFFFF;
  border-radius: 20px;
  padding: 20px 24px;
  box-shadow: 0 8px 24px rgba(11, 25, 44, 0.2);
  display: flex;
  flex-direction: column;
  gap: 12px;
  border: 1px solid rgba(0, 212, 255, 0.3);
  position: relative;
  overflow: hidden;
}

.smart-advice-banner-card::before {
  content: '';
  position: absolute;
  top: -20px;
  right: -20px;
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: radial-gradient(circle, var(--aura-cyan-glow) 0%, transparent 70%);
  pointer-events: none;
}

.advice-badge-top {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
  font-weight: 800;
  color: var(--aura-cyan);
  text-transform: uppercase;
}

.advice-title-text {
  font-family: var(--font-heading);
  font-size: 17px;
  font-weight: 800;
  line-height: 1.4;
  color: #FFFFFF;
}

.advice-savings-pill {
  background: rgba(0, 200, 83, 0.15);
  border: 1px solid rgba(0, 200, 83, 0.4);
  color: #4ADE80;
  padding: 6px 14px;
  border-radius: 12px;
  font-size: 12.5px;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
}

/* HISTORICAL CONSUMPTION DIDACTIC CHART */
.didactic-chart-card {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 20px;
  padding: 22px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.chart-header-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.chart-title-lbl {
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 800;
  color: var(--deep-indigo);
  display: flex;
  align-items: center;
  gap: 8px;
}

.chart-sub-tag {
  font-size: 11px;
  font-family: var(--font-mono);
  background: #F1F5F9;
  padding: 3px 8px;
  border-radius: 6px;
  color: var(--text-muted);
  font-weight: 600;
}

/* Visual Bars Stage */
.consumption-bars-wrapper {
  display: flex;
  align-items: flex-end;
  justify-content: space-around;
  height: 160px;
  padding: 10px 10px 0 10px;
  border-bottom: 1.5px solid #F1F5F9;
  position: relative;
}

.chart-threshold-line {
  position: absolute;
  top: 55px;
  left: 0;
  right: 0;
  border-top: 1.5px dashed #EF4444;
  display: flex;
  justify-content: flex-end;
}

.threshold-tag {
  font-size: 10px;
  font-weight: 800;
  color: #EF4444;
  background: #FEF2F2;
  padding: 2px 7px;
  border-radius: 4px;
  transform: translateY(-10px);
}

.month-bar-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  z-index: 2;
}

.bar-pill {
  width: 48px;
  border-radius: 10px 10px 0 0;
  background: #CBD5E1;
  transition: all 0.3s ease;
  position: relative;
}

.bar-pill.peak-travel {
  background: linear-gradient(180deg, #EF4444 0%, #DC2626 100%);
  box-shadow: 0 4px 12px rgba(239, 68, 68, 0.25);
}

.bar-pill.current-feb {
  background: linear-gradient(180deg, var(--movistar-blue) 0%, #0066CC 100%);
}

.bar-val-lbl {
  font-size: 11px;
  font-weight: 800;
  color: #FFFFFF;
  position: absolute;
  top: 6px;
  left: 50%;
  transform: translateX(-50%);
}

.month-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-secondary);
}

.chart-diagnostic-footer {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.5;
  background: #FFFBEB;
  border: 1px solid #FDE68A;
  border-radius: 12px;
  padding: 12px 16px;
}

/* Call-to-action in App */
.btn-app-action-main {
  width: 100%;
  background: linear-gradient(135deg, var(--movistar-blue), #0066CC);
  color: #FFFFFF;
  border: none;
  padding: 16px;
  border-radius: 16px;
  font-family: var(--font-heading);
  font-size: 15px;
  font-weight: 800;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  box-shadow: 0 6px 18px rgba(1, 157, 244, 0.3);
  transition: all var(--transition-fast);
}

.btn-app-action-main:active {
  transform: scale(0.98);
}

/* ==========================================================================
   PANTALLA 2: LLAMADA ENTRANTE & LLAMADA EN CURSO DE CARLOS
   ========================================================================== */
.incoming-call-fullscreen-stage {
  flex: 1;
  min-height: calc(100dvh - 44px);
  background: linear-gradient(180deg, #0F172A 0%, #020617 100%);
  color: #FFFFFF;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 48px 28px 40px 28px;
  position: relative;
}

.caller-id-hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  margin-top: 24px;
}

.caller-avatar-circle {
  width: 96px;
  height: 96px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--movistar-blue), var(--aura-cyan));
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 34px;
  font-weight: 800;
  margin-bottom: 20px;
  box-shadow: 0 0 40px var(--aura-cyan-glow);
  position: relative;
}

.caller-name-main {
  font-family: var(--font-heading);
  font-size: 26px;
  font-weight: 800;
  color: #FFFFFF;
  margin-bottom: 6px;
}

.caller-role-subtitle {
  font-size: 14px;
  color: var(--aura-cyan);
  font-weight: 600;
}

.caller-status-timer {
  font-family: var(--font-mono);
  font-size: 15px;
  color: #94A3B8;
  margin-top: 10px;
}

/* Call Actions Buttons (Accept / Hangup) */
.incoming-call-actions-row {
  display: flex;
  justify-content: space-around;
  align-items: center;
  margin-bottom: 24px;
}

.call-circle-btn {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
  cursor: pointer;
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.4);
  transition: all 0.2s ease;
}

.call-circle-btn.hangup {
  background: #EF4444;
}

.call-circle-btn.accept {
  background: #00C853;
  box-shadow: 0 0 35px rgba(0, 200, 83, 0.6);
  animation: pulseCallBtn 1.5s infinite;
}

.call-circle-btn:active {
  transform: scale(0.92);
}

/* LIVE IN-CALL DIALOGUE & VALERIA THOUGHT BOX */
.live-call-dialogue-box {
  background: rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 20px;
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin: 18px 0;
}

.carlos-voice-transcript {
  font-size: 13.5px;
  line-height: 1.55;
  color: #F1F5F9;
}

.valeria-thought-bubble {
  background: rgba(0, 212, 255, 0.12);
  border-left: 3px solid var(--aura-cyan);
  border-radius: 10px;
  padding: 10px 14px;
  font-size: 12.5px;
  color: var(--aura-cyan);
  font-style: italic;
  line-height: 1.45;
}

/* Oscillating Speech Wave in Call */
.voice-wave-mini-stage {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  height: 24px;
}

.voice-wave-bar {
  width: 3px;
  height: 8px;
  background: var(--aura-cyan);
  border-radius: 2px;
  animation: audioStreamPulse 0.7s infinite alternate;
}

.voice-wave-bar:nth-child(2) { height: 18px; animation-delay: 0.15s; }
.voice-wave-bar:nth-child(3) { height: 24px; animation-delay: 0.3s; }
.voice-wave-bar:nth-child(4) { height: 14px; animation-delay: 0.45s; }

/* ==========================================================================
   BOTTOM DIRECTOR BAR (RECORDING CONTROLLER)
   ========================================================================== */
.client-director-bar {
  position: fixed;
  bottom: 16px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(11, 25, 44, 0.94);
  backdrop-filter: blur(20px);
  border: 1px solid rgba(0, 212, 255, 0.35);
  border-radius: 30px;
  padding: 6px 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  z-index: 1000;
}

.client-director-bar a,
.client-director-bar button {
  background: rgba(255, 255, 255, 0.12);
  color: #FFFFFF;
  border: 1px solid rgba(255, 255, 255, 0.2);
  padding: 6px 14px;
  border-radius: 14px;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: all var(--transition-fast);
}

.client-director-bar button.active {
  background: var(--movistar-blue);
  border-color: var(--movistar-blue);
}

@keyframes screenFadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulseCallBtn {
  0%, 100% { box-shadow: 0 0 20px rgba(0, 200, 83, 0.4); }
  50% { box-shadow: 0 0 35px rgba(0, 200, 83, 0.8); }
}

/* ==========================================================================
   WHATSAPP SIMULATOR - VALERIA MENDOZA (100% FULLSCREEN & RESPONSIVE)
   Directivas: DESIGN.md • Strict Light Tech • Zero Mockups • Fullscreen Native
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;700&family=Outfit:wght@500;600;700;800&display=swap');
@import './variables.css';
@import './components/aura-orb.css';

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

html, body {
  width: 100%;
  min-height: 100dvh;
  overflow-x: hidden;
  background-color: #EFEAE2;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  color: #111B21;
}

/* Indicador de Progreso Tipo Stories Superior */
.tap-story-progress-bar {
  position: absolute;
  top: 6px;
  left: 16px;
  right: 16px;
  display: flex;
  gap: 6px;
  z-index: 70;
}

.story-bar-segment {
  flex: 1;
  height: 3.5px;
  background: rgba(0, 0, 0, 0.15);
  border-radius: 3px;
  overflow: hidden;
  transition: all 0.3s ease;
}

.story-bar-segment.active {
  background: #019DF4;
  box-shadow: 0 0 8px rgba(1, 157, 244, 0.6);
}

.story-bar-segment.completed {
  background: #00C853;
}

/* Contenedor Principal: 100% Pantalla Completa en Móvil, Centrado Responsivo en Desktop */
.phone-container {
  width: 100%;
  min-height: 100dvh;
  max-width: 820px;
  margin: 0 auto;
  background: #EFEAE2;
  background-image: radial-gradient(rgba(1, 157, 244, 0.04) 1px, transparent 0);
  background-size: 24px 24px;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: 0 4px 30px rgba(0, 0, 0, 0.05);
}

@media (max-width: 820px) {
  .phone-container {
    max-width: 100vw;
    box-shadow: none;
  }
}

.phone-inner-screen {
  width: 100%;
  flex: 1;
  display: flex;
  flex-direction: column;
  position: relative;
}

/* --- WhatsApp Header --- */
.whatsapp-chat-header {
  background: #F0F2F5;
  padding: 14px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid #D1D7DB;
  position: sticky;
  top: 0;
  z-index: 60;
}

.chat-partner-info {
  display: flex;
  align-items: center;
  gap: 12px;
}

.partner-avatar-wrapper {
  position: relative;
}

.partner-avatar-img {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--movistar-blue), var(--aura-cyan));
  display: flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 16px;
  box-shadow: 0 0 12px var(--aura-cyan-glow);
}

.partner-online-indicator {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: #00C853;
  border: 2px solid #FFFFFF;
}

.partner-text-block h3 {
  font-size: 15.5px;
  font-weight: 700;
  color: #111B21;
  display: flex;
  align-items: center;
  gap: 6px;
}

.partner-status-sub {
  font-size: 12px;
  color: #008738;
  font-weight: 500;
}

.chat-header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  color: #54656F;
}

/* --- Chat Messages Scroll Area --- */
.whatsapp-chat-body {
  flex: 1;
  padding: 20px 18px 90px 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  overflow-y: auto;
}

/* Chat Bubbles */
.chat-msg-row {
  display: flex;
  width: 100%;
  animation: msgPop 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.chat-msg-row.incoming {
  justify-content: flex-start;
}

.chat-msg-row.outgoing {
  justify-content: flex-end;
}

.chat-bubble {
  max-width: 82%;
  padding: 10px 14px;
  border-radius: 12px;
  position: relative;
  font-size: 14px;
  line-height: 1.45;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.12);
}

.chat-bubble.incoming {
  background: #FFFFFF;
  color: #111B21;
  border-top-left-radius: 2px;
}

.chat-bubble.outgoing {
  background: #D9FDD3;
  color: #111B21;
  border-top-right-radius: 2px;
}

.msg-timestamp {
  font-size: 10.5px;
  color: #667781;
  float: right;
  margin-top: 4px;
  margin-left: 8px;
  display: flex;
  align-items: center;
  gap: 3px;
}

/* Interactive WhatsApp Action Buttons Inside Bubbles */
.chat-cta-btn-group {
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  border-top: 1px solid rgba(0, 0, 0, 0.06);
  padding-top: 8px;
}

.chat-cta-btn {
  background: #FFFFFF;
  border: 1px solid rgba(1, 157, 244, 0.4);
  color: var(--movistar-blue);
  font-size: 13px;
  font-weight: 700;
  padding: 9px 12px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.chat-cta-btn:hover {
  background: var(--aura-cyan-subtle);
  border-color: var(--movistar-blue);
}

/* Audio Player Bubble */
.audio-player-bubble {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  min-width: 240px;
}

.audio-play-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--movistar-blue);
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  cursor: pointer;
}

.audio-track-wave {
  flex: 1;
  height: 4px;
  background: rgba(0, 0, 0, 0.12);
  border-radius: 2px;
  position: relative;
}

.audio-track-progress {
  width: 65%;
  height: 100%;
  background: var(--movistar-blue);
  border-radius: 2px;
}

/* --- WhatsApp Footer Input Bar --- */
.whatsapp-chat-footer {
  background: #F0F2F5;
  padding: 10px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  position: sticky;
  bottom: 0;
  z-index: 60;
  border-top: 1px solid #D1D7DB;
}

.chat-input-fake {
  flex: 1;
  background: #FFFFFF;
  border-radius: 24px;
  padding: 10px 18px;
  font-size: 14px;
  color: #111B21;
  border: none;
  outline: none;
}

.chat-mic-btn {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: #00A884;
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  cursor: pointer;
}

/* Floating Director Controller */
.valeria-director-bar {
  position: fixed;
  bottom: 16px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(11, 25, 44, 0.94);
  backdrop-filter: blur(20px);
  border: 1px solid rgba(0, 212, 255, 0.35);
  border-radius: 30px;
  padding: 6px 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  z-index: 1000;
}

.valeria-director-bar a,
.valeria-director-bar button {
  background: rgba(255, 255, 255, 0.12);
  color: #FFFFFF;
  border: 1px solid rgba(255, 255, 255, 0.2);
  padding: 6px 14px;
  border-radius: 14px;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: all var(--transition-fast);
}

.valeria-director-bar button.active {
  background: var(--movistar-blue);
  border-color: var(--movistar-blue);
}

@keyframes msgPop {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

args.ReplacementContent:
/* ==========================================================================
   RESPONSIVE MEDIA QUERIES PARA MÓVIL Y TABLET (100% PANTALLA COMPLETA)
   ========================================================================== */
@media (max-width: 1024px) {
  .sfdc-workspace-layout {
    flex-direction: column;
  }

  .sfdc-sidebar {
    width: 100%;
    border-right: none;
    border-bottom: 1px solid #E2E8F0;
    padding: 10px 16px;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }

  .sfdc-nav-list {
    flex-direction: row;
    overflow-x: auto;
    gap: 6px;
  }

  .sidebar-shift-card {
    display: none;
  }

  .active-call-workspace-layout {
    grid-template-columns: 1fr;
  }

  .screen1-dialer-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .sfdc-global-header {
    padding: 0 12px;
    height: auto;
    padding-top: 10px;
    padding-bottom: 10px;
    flex-wrap: wrap;
    gap: 8px;
  }

