/* ==========================================================================
   WHATSAPP VALERIA MENDOZA - 100% RESPONSIVE & FULLSCREEN OPTIMIZATION
   Directivas: DESIGN.md • Strict Light Tech • Zero Mockups • WhatsApp Web/Native
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;700&family=Outfit:wght@500;600;700;800&display=swap');
@import './variables.css';
@import './components/aura-orb.css';

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

html, body {
  width: 100%;
  min-height: 100dvh;
  background-color: #EFEAE2;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  color: #111B21;
  display: flex;
  flex-direction: column;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* Master Responsive Stage: 100% Fullscreen on Mobile, Centered Web App on Desktop */
.wa-app-viewport {
  width: 100%;
  min-height: 100dvh;
  max-width: 860px;
  margin: 0 auto;
  background: #EFEAE2;
  background-image: radial-gradient(rgba(1, 157, 244, 0.04) 1px, transparent 0);
  background-size: 24px 24px;
  display: flex;
  flex-direction: column;
  position: relative;
  border-left: 1px solid #D1D7DB;
  border-right: 1px solid #D1D7DB;
  box-shadow: 0 4px 30px rgba(0, 0, 0, 0.04);
}

@media (max-width: 860px) {
  .wa-app-viewport {
    max-width: 100vw;
    border-left: none;
    border-right: none;
    box-shadow: none;
  }
}

/* --- Top Tap Story Progress Bar --- */
.tap-story-progress-bar {
  position: absolute;
  top: 4px;
  left: 14px;
  right: 14px;
  display: flex;
  gap: 6px;
  z-index: 80;
}

.story-bar-segment {
  flex: 1;
  height: 3.5px;
  background: rgba(0, 0, 0, 0.18);
  border-radius: 3px;
  overflow: hidden;
  transition: all 0.3s ease;
}

.story-bar-segment.active {
  background: #019DF4;
  box-shadow: 0 0 8px rgba(1, 157, 244, 0.7);
}

.story-bar-segment.completed {
  background: #00C853;
}

/* --- WhatsApp Header Navigation Bar --- */
.wa-nav-header {
  background: #F0F2F5;
  padding: 14px 18px 12px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid #D1D7DB;
  position: sticky;
  top: 0;
  z-index: 70;
}

.wa-nav-left {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
}

.wa-back-btn {
  display: flex;
  align-items: center;
  color: var(--movistar-blue);
  font-size: 13px;
  font-weight: 600;
}

.wa-unread-badge {
  background: var(--movistar-blue);
  color: #FFFFFF;
  font-size: 11px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 10px;
  margin-left: 2px;
}

.wa-contact-card {
  display: flex;
  align-items: center;
  gap: 12px;
}

.wa-avatar-box {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--movistar-blue), var(--aura-cyan));
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  box-shadow: 0 0 12px var(--aura-cyan-glow);
}

.wa-contact-details h2 {
  font-size: 15.5px;
  font-weight: 700;
  color: #111B21;
  display: flex;
  align-items: center;
  gap: 5px;
}

.wa-verified-icon {
  width: 15px;
  color: #019DF4;
  fill: #019DF4;
}

.wa-contact-status {
  font-size: 12px;
  color: #008738;
  font-weight: 500;
}

.wa-contact-status.typing {
  color: var(--movistar-blue);
  font-weight: 600;
  font-style: italic;
}

.wa-nav-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.wa-nav-icon-btn {
  background: none;
  border: none;
  color: #54656F;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
  border-radius: 50%;
  transition: color var(--transition-fast);
}

.wa-nav-icon-btn:hover {
  color: var(--deep-indigo);
}

/* --- WhatsApp Chat Messages Body (Tap-to-Advance Zone) --- */
.wa-chat-body {
  flex: 1;
  padding: 18px 20px 90px 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  overflow-y: auto;
  cursor: pointer;
}

/* Tap Hint Helper Pill */
.tap-hint-pill {
  align-self: center;
  background: rgba(1, 157, 244, 0.12);
  border: 1px solid rgba(1, 157, 244, 0.35);
  color: var(--movistar-blue);
  padding: 6px 14px;
  border-radius: 20px;
  font-size: 11.5px;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
  animation: pulseTapHint 2s infinite;
}

/* Encryption Pill */
.wa-encryption-pill {
  align-self: center;
  background: #FFEECD;
  border: 1px solid #F6D896;
  color: #54656F;
  border-radius: 8px;
  padding: 6px 12px;
  font-size: 11px;
  text-align: center;
  max-width: 420px;
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
}

/* Date Divider */
.wa-date-divider {
  align-self: center;
  background: #FFFFFF;
  color: #54656F;
  padding: 4px 12px;
  border-radius: 8px;
  font-size: 11.5px;
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
  margin: 4px 0 8px 0;
}

/* Message Bubbles */
.wa-bubble {
  max-width: 84%;
  padding: 10px 14px;
  border-radius: 12px;
  font-size: 14px;
  line-height: 1.45;
  position: relative;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.12);
  animation: msgSlideIn 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.wa-bubble.incoming {
  align-self: flex-start;
  background: #FFFFFF;
  color: #111B21;
  border-top-left-radius: 2px;
}

.wa-bubble.outgoing {
  align-self: flex-end;
  background: #D9FDD3;
  color: #111B21;
  border-top-right-radius: 2px;
}

.wa-bubble-time {
  font-size: 10.5px;
  color: #667781;
  float: right;
  margin-top: 4px;
  margin-left: 8px;
  display: flex;
  align-items: center;
  gap: 3px;
}

.wa-ticks-blue {
  width: 14px;
  color: #53BDEB;
}

/* --- Interactive Offer Card in WhatsApp --- */
.wa-offer-card {
  background: #F8FAFC;
  border: 1.5px solid rgba(1, 157, 244, 0.35);
  border-radius: 14px;
  padding: 14px;
  margin-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.wa-offer-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.wa-offer-badge-save {
  font-size: 11px;
  font-weight: 800;
  background: #DCFCE7;
  color: #166534;
  padding: 3px 8px;
  border-radius: 6px;
}

.wa-offer-price-grid {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 10px;
  padding: 10px 14px;
}

.wa-price-old {
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 800;
  color: #EF4444;
  text-decoration: line-through;
}

.wa-price-new {
  font-family: var(--font-heading);
  font-size: 18px;
  font-weight: 800;
  color: var(--movistar-blue);
}

.wa-offer-features {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.45;
}

.wa-btn-1touch {
  width: 100%;
  background: linear-gradient(135deg, var(--movistar-blue), #0066CC);
  color: #FFFFFF;
  border: none;
  padding: 11px;
  border-radius: 10px;
  font-family: var(--font-heading);
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  box-shadow: 0 4px 12px rgba(1, 157, 244, 0.3);
  transition: transform 0.2s ease;
}

.wa-btn-1touch:active {
  transform: scale(0.98);
}

/* Audio Player Bubble */
.audio-player-bubble {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 4px;
}

.audio-play-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--movistar-blue);
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  cursor: pointer;
}

.audio-track-wave {
  flex: 1;
  height: 4px;
  background: rgba(0, 0, 0, 0.12);
  border-radius: 2px;
  position: relative;
}

.audio-track-progress {
  width: 65%;
  height: 100%;
  background: var(--movistar-blue);
  border-radius: 2px;
}

/* --- WhatsApp Bottom Input Bar --- */
.wa-input-bar {
  background: #F0F2F5;
  padding: 10px 16px;
  display: flex;
  align-items: center;
  gap: 10px;
  position: sticky;
  bottom: 0;
  z-index: 70;
  border-top: 1px solid #D1D7DB;
}

.wa-action-icon-btn {
  background: none;
  border: none;
  color: #54656F;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
}

.wa-text-input-box {
  flex: 1;
  background: #FFFFFF;
  border-radius: 24px;
  padding: 10px 16px;
  font-size: 14px;
  color: #111B21;
  border: none;
  outline: none;
}

.wa-mic-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: #00A884;
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  cursor: pointer;
}

/* Floating Director Controller */
.valeria-director-bar {
  position: fixed;
  bottom: 16px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(11, 25, 44, 0.94);
  backdrop-filter: blur(20px);
  border: 1px solid rgba(0, 212, 255, 0.35);
  border-radius: 30px;
  padding: 6px 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  z-index: 1000;
}

.valeria-director-bar a,
.valeria-director-bar button {
  background: rgba(255, 255, 255, 0.12);
  color: #FFFFFF;
  border: 1px solid rgba(255, 255, 255, 0.2);
  padding: 6px 14px;
  border-radius: 14px;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: all var(--transition-fast);
}

.valeria-director-bar button.active {
  background: var(--movistar-blue);
  border-color: var(--movistar-blue);
}

@keyframes msgSlideIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes pulseTapHint {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.03); box-shadow: 0 0 12px rgba(1, 157, 244, 0.3); }
}

